// Format WMS release dispatch packet
const body = $input.first().json.body || $input.first().json;
const packets = body.dispatch_packets || [];

return packets.map(p => ({
    json: {
        wms_target: p.target_system,
        dispatch_id: p.dispatch_id,
        sku: p.sku,
        allocated_qty: p.allocated_qty,
        scheduled_date: p.scheduled_dispatch_date,
        released_at: new Date().toISOString()
    }
}));
